/* Token Radar: ink background, graphite panels, amber for the radar's own voice, and two status colours
   used only where they carry data — growth up or down, and the farm planner's verdict. Figures are set in
   a tabular mono so they can be compared straight down a column. */

:root {
  --ink: #0a0e14; --panel: #121924; --panel-2: #18202e;
  --line: #232d3d; --line-soft: #1b2431;
  --text: #eef2f8; --muted: #aab7c9; --faint: #8695a9;
  --accent: #f0b429; --accent-dim: #7a5c12;
  --up: #4fc78a; --down: #f2837f; --radius: 10px;
}
* { box-sizing: border-box; }
html { background: var(--ink); }
body {
  margin: 0; padding: 0 0 56px; background: var(--ink); color: var(--text);
  font: 400 14px/1.5 "Segoe UI", system-ui, -apple-system, sans-serif;
  -webkit-font-smoothing: antialiased;
}
.num { font-family: "Cascadia Mono", "SF Mono", Consolas, ui-monospace, monospace; font-variant-numeric: tabular-nums; }
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }

/* header */
.top {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 32px;
  padding: 18px 32px 14px; border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, #101725 0%, var(--ink) 100%);
}
.brand { display: flex; align-items: baseline; gap: 14px; min-width: 0; }
.mark { width: 12px; height: 12px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 4px rgba(240,180,41,.14); flex: none; }
h1 { font-size: 26px; font-weight: 650; letter-spacing: -.02em; margin: 0; white-space: nowrap; }
.tag { color: var(--muted); font-size: 13px; margin: 0; }
.facts { display: flex; gap: 26px; margin: 0; }
.facts div { text-align: right; }
.facts dt { color: var(--faint); font-size: 11px; letter-spacing: .06em; text-transform: uppercase; }
.facts dd { margin: 2px 0 0; font-size: 18px; font-weight: 600; }
.facts dd.ok { color: var(--accent); }

/* the fitted numbers, on the board itself */
.model-strip { display: grid; grid-template-columns: 1.35fr 1fr 1fr 1fr; gap: 1px; background: var(--line-soft); border-bottom: 1px solid var(--line); }
.model-strip > div { background: var(--panel); padding: 10px 18px; }
.model-strip h2 { font-size: 11px; letter-spacing: .07em; text-transform: uppercase; color: var(--faint); margin: 0 0 5px; font-weight: 600; }
.model-strip p { margin: 0; font-size: 13px; color: var(--muted); }
.model-strip .eq { color: var(--text); font-size: 13px; }
.model-strip .eq b, .model-strip .win { color: var(--accent); font-weight: 600; }
.model-strip .win { color: var(--up); }

.views { display: flex; gap: 4px; padding: 10px 32px 0; }
.views button { background: none; border: 1px solid transparent; color: var(--muted); padding: 7px 14px; border-radius: 999px; font: inherit; font-size: 13px; cursor: pointer; }
.views button:hover { color: var(--text); background: var(--panel); }
.views button[aria-current="page"] { color: var(--ink); background: var(--accent); font-weight: 600; }
main { padding: 16px 32px 0; }

/* board: a filter rail and the table */
.board { display: grid; grid-template-columns: 236px 1fr; gap: 22px; align-items: start; }
.rail { position: sticky; top: 16px; display: flex; flex-direction: column; gap: 18px; }
.field { display: flex; flex-direction: column; gap: 6px; }
.field label { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: var(--faint); font-weight: 600; }
.field input, .field select { width: 100%; background: var(--panel); color: var(--text); border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; font: inherit; font-size: 13px; }
.field input:focus, .field select:focus { outline: 2px solid var(--accent-dim); border-color: var(--accent-dim); }
.chips { display: flex; flex-wrap: wrap; gap: 6px; }
.chips button { background: var(--panel); border: 1px solid var(--line); color: var(--muted); border-radius: 999px; padding: 5px 11px; font: inherit; font-size: 12px; cursor: pointer; }
.chips button[aria-pressed="true"] { border-color: var(--accent); color: var(--accent); background: rgba(240,180,41,.08); }
.count { color: var(--muted); font-size: 12px; }
.count b { color: var(--text); font-size: 15px; }
.reset { background: none; border: 0; color: var(--faint); font: inherit; font-size: 12px; cursor: pointer; text-align: left; padding: 0; }
.reset:hover { color: var(--accent); }

.table-wrap { border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; }
table { border-collapse: collapse; width: 100%; }
thead th { position: sticky; top: 0; z-index: 1; background: var(--panel-2); color: var(--muted); font-size: 11px; letter-spacing: .05em; text-transform: uppercase; font-weight: 600; text-align: left; padding: 10px 12px; border-bottom: 1px solid var(--line); white-space: nowrap; cursor: pointer; }
thead th:hover { color: var(--text); }
thead th .arw { color: var(--accent); font-size: 10px; }
tbody td { padding: 7px 10px; border-bottom: 1px solid var(--line-soft); vertical-align: middle; }
tbody tr:hover { background: var(--panel); }
tbody tr:last-child td { border-bottom: 0; }
td.r, th.r { text-align: right; }
td.nowrap, th.nowrap { white-space: nowrap; }
.rank { color: var(--faint); font-size: 12px; }
.who { display: flex; flex-direction: column; gap: 1px; min-width: 170px; }
.who .nm { font-weight: 600; }
.who .sub, td .sub { color: var(--faint); font-size: 11.5px; }
td.nowrap .sub { display: block; }
.tierbar { display: inline-flex; align-items: center; gap: 7px; }
.back { display: block; font-size: 12px; margin-bottom: 4px; color: var(--muted); }
.back:hover { color: var(--accent); }
.val { font-weight: 650; font-size: 14px; }
.up { color: var(--up); }
.down { color: var(--down); }
.mut { color: var(--faint); }
.empty { padding: 40px; text-align: center; color: var(--muted); border: 1px dashed var(--line); border-radius: var(--radius); }

.chip { display: inline-block; border-radius: 5px; padding: 2px 7px; font-size: 11px; font-weight: 600; letter-spacing: .02em; border: 1px solid transparent; white-space: nowrap; }
.chip.watchlist, .chip.thin { color: var(--accent); border-color: var(--accent-dim); background: rgba(240,180,41,.09); }
.chip.extended { color: #7fb2e8; border-color: #2a4260; background: rgba(127,178,232,.08); }
.chip.early, .chip.skip { color: var(--muted); border-color: var(--line); background: var(--panel-2); }
.chip.farm { color: var(--up); border-color: #22523a; background: rgba(70,180,122,.09); }

/* one protocol: the record and its derivation on the left, the farm plan on the right, so the whole
   answer for one protocol fits one 1440x900 screen without scrolling */
.detail { display: grid; grid-template-columns: 440px 1fr; gap: 18px; align-items: start; }
.stack { display: flex; flex-direction: column; gap: 11px; }
.card { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 12px 15px; }
.card > h2 { font-size: 12px; letter-spacing: .06em; text-transform: uppercase; color: var(--faint); margin: 0 0 9px; font-weight: 600; }
.head { grid-column: 1 / -1; display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }
.head h2 { font-size: 22px; margin: 0 0 4px; letter-spacing: -.01em; }
.head .sub { color: var(--muted); font-size: 13px; }
.hero { text-align: right; }
.hero .big { font-size: 32px; font-weight: 680; letter-spacing: -.02em; color: var(--accent); }
.hero .cap { color: var(--faint); font-size: 11px; letter-spacing: .06em; text-transform: uppercase; }
.kv { display: grid; grid-template-columns: 1fr auto; gap: 5px 14px; margin: 0; }
.kv dt { color: var(--muted); font-size: 12.5px; }
.kv dd { margin: 0; text-align: right; font-size: 13px; }
.kv dd.hi { color: var(--accent); font-weight: 600; }
.derive { font-family: "Cascadia Mono", Consolas, ui-monospace, monospace; font-size: 11.5px; line-height: 1.45; color: var(--muted); background: var(--panel-2); border: 1px solid var(--line-soft); border-radius: 8px; padding: 10px 12px; margin: 0; white-space: pre-wrap; }
.derive b { color: var(--text); font-weight: 600; }
ol.steps { list-style: none; counter-reset: s; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 9px; }
ol.steps li { counter-increment: s; display: grid; grid-template-columns: 22px 1fr; gap: 10px; }
ol.steps li::before { content: counter(s); display: flex; align-items: center; justify-content: center; height: 21px; border-radius: 6px; background: var(--accent-dim); color: var(--accent); font-size: 11px; font-weight: 700; }
ol.steps p { margin: 0; font-size: 12.5px; line-height: 1.45; }
.bar { height: 8px; border-radius: 4px; background: var(--panel-2); position: relative; overflow: hidden; margin: 6px 0 2px; }
.bar span { position: absolute; top: 0; bottom: 0; background: var(--accent-dim); }
.method p { font-size: 13.5px; color: var(--muted); margin: 0 0 12px; }
.method code { font-family: "Cascadia Mono", Consolas, monospace; font-size: 12.5px; color: var(--text); background: var(--panel-2); padding: 1px 5px; border-radius: 4px; }
footer { padding: 26px 32px 0; color: var(--faint); font-size: 12px; border-top: 1px solid var(--line-soft); margin-top: 28px; }
footer p { margin: 0 0 6px; max-width: 90ch; }
```

### app.js

21467 bytes, 277 lines

```js
// Token Radar's page: it renders the one object the program wrote (window.RADAR, from ../data.js) and
// computes nothing of its own, so what a reader sees is the board the gate read and the screenshots and
// the source cannot disagree. Routes are the hash: '' the board, '#/p/<slug>' one protocol, '#/live' the
// traded comps, '#/method' the model.

(function () {
  'use strict';
  var R = window.RADAR;
  var view = document.getElementById('view');
  var S = { q: '', tier: '', verdict: '', category: '', chain: '', minTvl: 0, sort: 'rank', dir: 1, limit: 60 };
  var nf = new Intl.NumberFormat('en-US');

  function money(v) {
    if (!isFinite(v)) return '—';
    if (v >= 1e12) return '$' + (v / 1e12).toFixed(2) + 'T';
    if (v >= 1e9) return '$' + (v / 1e9).toFixed(2) + 'B';
    if (v >= 1e6) return '$' + (v / 1e6).toFixed(1) + 'M';
    if (v >= 1e3) return '$' + Math.round(v / 1e3) + 'K';
    return '$' + Math.round(v);
  }
  var exact = function (v) { return isFinite(v) ? '$' + nf.format(Math.round(v)) : '—'; };
  var pct = function (v) { return v === null || !isFinite(v) ? '—' : (v > 0 ? '+' : '') + v.toFixed(1) + '%'; };
  var mult = function (v) { return !isFinite(v) ? '—' : (v >= 10 ? v.toFixed(1) : v.toFixed(2)) + '×'; };
  function months(d) {
    if (d === null) return 'no listing day';
    if (d < 45) return d + ' days';
    return d < 700 ? (d / 30.44).toFixed(1) + ' months' : (d / 365.25).toFixed(1) + ' years';
  }
  function esc(s) {
    return String(s === null || s === undefined ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function el(tag, cls, html) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (html !== undefined) e.innerHTML = html;
    return e;
  }
  var tag = function (t) { return t === 'extended' ? 'above floor' : t; };
  var rate = function (r) { return r.change_7d === null ? '' : r.change_7d >= 0 ? 'up' : 'down'; };

  // ---- filters -------------------------------------------------------------------

  function filtered() {
    var rows = R.rows.filter(function (r) {
      if (S.tier && r.tier !== S.tier) return false;
      if (S.verdict && r.verdict !== S.verdict) return false;
      if (S.category && (r.category || 'Uncategorised') !== S.category) return false;
      if (S.chain && r.chains.indexOf(S.chain) === -1) return false;
      if (S.minTvl && r.tvl_usd < S.minTvl) return false;
      return !S.q || r.name.toLowerCase().indexOf(S.q.toLowerCase()) !== -1 || r.slug.indexOf(S.q.toLowerCase()) !== -1;
    });
    rows.sort(function (a, b) {
      var x = S.sort === 'verdict' ? { farm: 0, thin: 1, skip: 2 }[a.verdict] : S.sort === 'name' ? a.name.toLowerCase() : a[S.sort];
      var y = S.sort === 'verdict' ? { farm: 0, thin: 1, skip: 2 }[b.verdict] : S.sort === 'name' ? b.name.toLowerCase() : b[S.sort];
      var d = x < y ? -1 : x > y ? 1 : 0;
      return (d === 0 ? a.rank - b.rank : d) * S.dir;
    });
    return rows;
  }
  function distinct(field) {
    var c = {};
    R.rows.forEach(function (r) {
      (Array.isArray(r[field]) ? r[field] : [r[field] || 'Uncategorised']).forEach(function (k) { c[k] = (c[k] || 0) + 1; });
    });
    return Object.keys(c).sort(function (a, b) { return c[b] - c[a] || (a < b ? -1 : 1); });
  }
  function chipRow(id, pairs, current) {
    return '<div class="chips" id="' + id + '">' + pairs.map(function (p) {
      return '<button type="button" data-v="' + p[0] + '" aria-pressed="' + (current === p[0]) + '">' + p[1] + '</button>';
    }).join('') + '</div>';
  }
  function pickRow(id, list, current) {
    return '<select id="' + id + '"><option value="">all</option>' + list.map(function (c) {
      return '<option value="' + esc(c) + '"' + (current === c ? ' selected' : '') + '>' + esc(c) + '</option>';
    }).join('') + '</select>';
  }

  // ---- shell ---------------------------------------------------------------------

  function shell() {
    document.getElementById('tag').textContent = R.board_size + ' protocols that record no token, ranked by what a token launch would be worth — sealed DefiLlama snapshot of ' + R.as_of;
    document.getElementById('facts').innerHTML = [
      ['Watchlist', R.watchlist_covered + '/' + R.watchlist_size, R.watchlist_covered === R.watchlist_size],
      ['Rows ranked', R.board_size, false], ['Comps fitted', R.model.n, false], ['Snapshot', R.as_of, false]
    ].map(function (f) { return '<div><dt>' + f[0] + '</dt><dd' + (f[2] ? ' class="ok"' : '') + '>' + f[1] + '</dd></div>'; }).join('');

    // The model strip is the board's own claim about its own accuracy, measured on the snapshot.
    var b = R.model.beta, v = R.validation.rows;
    document.getElementById('strip').innerHTML = [
      ['The fitted model, ' + R.model_version,
        '<span class="eq">ln(mcap) = <b>' + b[0].toFixed(3) + '</b> + <b>' + b[1].toFixed(3) + '</b>·ln(TVL) + <b>' + b[2].toFixed(4) + '</b>·growth</span>' +
        '<p>Fit on ' + R.model.n + ' traded protocols, R² ' + R.model.r2.toFixed(3) + ', σ ' + R.model.sigma.toFixed(3) + '. Elasticity ' + b[1].toFixed(2) + ': a larger protocol trades at a <em>smaller</em> multiple of TVL.</p>'],
      ['Median error, left one out', '<span class="eq"><b>' + v[0].median_abs_log_error.toFixed(3) + '</b> ln units <span class="win">(×' + v[0].typical_ratio.toFixed(2) + ')</span></span><p>Measured, not asserted: each comp refitted without itself.</p>'],
      ['Flat multiple baseline', '<span class="eq">' + v[1].median_abs_log_error.toFixed(3) + ' (×' + v[1].typical_ratio.toFixed(2) + ')</span><p>TVL × the median mcap/TVL multiple of ' + R.model.flat_multiple.toFixed(3) + ', scored the same way.</p>'],
      ['Category-peers baseline', '<span class="eq">' + v[2].median_abs_log_error.toFixed(3) + ' (×' + v[2].typical_ratio.toFixed(2) + ')</span><p>The same multiple taken inside the protocol’s own category.</p>']
    ].map(function (c) { return '<div><h2>' + c[0] + '</h2><div>' + c[1] + '</div></div>'; }).join('');

    document.getElementById('foot').innerHTML =
      '<p>Source: ' + esc(R.source) + '. Every figure here was computed from that snapshot by the program that wrote this board: the model is <code>dashboard/model.mjs</code>, the planner <code>dashboard/farm.mjs</code>, the rows <code>dashboard/board.mjs</code> — the program imports them out of this same directory. The page is static, has no framework and no network, and computes nothing of its own, so the board and this source cannot disagree.</p>' +
      '<p>An implied value is this radar’s own claim about what a token would be worth if the protocol’s record stayed as it is. It is not a prediction that a token will be issued, and it is not investment advice. DefiLlama’s record is not proof: a protocol here may hold a token its record does not carry. Farming costs real money and can lose it.</p>';
  }

  // ---- the board -----------------------------------------------------------------

  function rail() {
    var r = el('aside', 'rail');
    r.innerHTML =
      '<div class="field"><label for="fq">Search</label><input id="fq" type="search" placeholder="name or slug" value="' + esc(S.q) + '"></div>' +
      '<div class="field"><label for="ftvl">Minimum TVL (USD)</label><input id="ftvl" type="number" min="0" step="1000000" placeholder="any" value="' + (S.minTvl || '') + '"></div>' +
      '<div class="field"><label>Tier</label>' + chipRow('ctier', [['', 'all'], ['watchlist', 'watchlist ' + R.tier_counts.watchlist], ['extended', 'above floor ' + R.tier_counts.extended], ['early', 'early ' + R.tier_counts.early]], S.tier) + '</div>' +
      '<div class="field"><label>Farm verdict</label>' + chipRow('cver', [['', 'all'], ['farm', 'farm ' + R.verdict_counts.farm], ['thin', 'thin ' + R.verdict_counts.thin], ['skip', 'skip ' + R.verdict_counts.skip]], S.verdict) + '</div>' +
      '<div class="field"><label for="fcat">Category</label>' + pickRow('fcat', distinct('category'), S.category) + '</div>' +
      '<div class="field"><label for="fchain">Chain</label>' + pickRow('fchain', distinct('chains').slice(0, 60), S.chain) + '</div>' +
      '<p class="count"></p><button class="reset" type="button">Reset every filter</button>';
    r.querySelector('#fq').oninput = function () { S.q = this.value; render(); };
    r.querySelector('#ftvl').oninput = function () { S.minTvl = Number(this.value) || 0; render(); };
    r.querySelector('#fcat').onchange = function () { S.category = this.value; render(); };
    r.querySelector('#fchain').onchange = function () { S.chain = this.value; render(); };
    r.querySelector('.reset').onclick = function () { S = { q: '', tier: '', verdict: '', category: '', chain: '', minTvl: 0, sort: 'rank', dir: 1, limit: 60 }; render(); };
